NUMSUB = json.load(open(D + 'tools/numsub_v38.json'))
def numsub(b, name):
    for row in NUMSUB.get(name, []):
        o, n = row['old'], row['new']
        if row.get('all'): b.rep_all(o, n)
        else: b.rep(o, n)

